# The UNTRUSTED half of the pythonTests harness. It executes the model's candidate code and answers the trusted
# parent's JSON requests from the resulting namespace. Everything about it is deliberately boring:
#
#   * it holds NO nonce and NO operator test code -- there is nothing in this address space to steal, which is the
#     property PythonTests_ChildProgramContainsNeitherNonceNorTestCode asserts on the generated bytes;
#   * it holds NO handle to the sandbox's stdout -- its stdout is a pipe the parent owns, so a forged verdict line
#     reaches the parent as ordinary data and never the surface C# reads;
#   * it decides the ANSWERS and nothing about the JUDGEMENT. That is exactly what a candidate is supposed to control.
#
# C# prepends one line, `_CANDIDATE_B64 = "<base64>"`, before this template. The candidate's own bytes are therefore
# base64 by the time they reach any Python parser, and base64 cannot terminate a string literal -- so no candidate,
# however adversarial its quoting, can escape into code anywhere.
import ast
import base64
import json
import os
import sys
import traceback

_REQUESTS = os.fdopen(int(os.environ["XE_REQ_FD"]), "rb")
_RESPONSES = os.fdopen(int(os.environ["XE_RES_FD"]), "wb")

# Anything the candidate prints goes to stderr, which the parent captures as candidate-controlled evidence. The
# response channel is its own inherited pipe precisely so that a chatty candidate cannot desynchronize the protocol.
sys.stdout = sys.stderr

_MAX_MESSAGE_CHARS = 2000

_namespace = {"__name__": "__candidate__"}
_load_error = None

try:
    exec(compile(base64.b64decode(_CANDIDATE_B64), "<candidate>", "exec"), _namespace)
except BaseException as error:  # noqa: BLE001 - a candidate may raise anything, including SystemExit
    traceback.print_exc(file=sys.stderr)
    _load_error = type(error).__name__ + ": " + str(error)[:_MAX_MESSAGE_CHARS]


def _send(payload):
    try:
        data = json.dumps(payload)
    except (TypeError, ValueError) as error:
        # A return value the boundary cannot carry is a NAMED failure of that call, never a silent success. It is the
        # stated cost of the proxy and it is surfaced rather than swallowed.
        data = json.dumps({"err": "the value is not JSON-serializable: " + str(error)[:_MAX_MESSAGE_CHARS]})
    _RESPONSES.write(data.encode("utf-8") + b"\n")
    _RESPONSES.flush()


def _evaluate(source):
    # Arbitrary setup runs HERE, in the child; only the final expression's value crosses the boundary. This is the
    # escape hatch for stateful and class-based tasks that a call-only proxy cannot express.
    tree = ast.parse(source, "<pyeval>", "exec")
    tail = tree.body.pop() if tree.body and isinstance(tree.body[-1], ast.Expr) else None
    exec(compile(tree, "<pyeval>", "exec"), _namespace)
    if tail is None:
        return None

    return eval(compile(ast.Expression(tail.value), "<pyeval>", "eval"), _namespace)


while True:
    _line = _REQUESTS.readline()
    if not _line:
        break

    try:
        _message = json.loads(_line.decode("utf-8", "replace"))
    except ValueError:
        _send({"err": "the request could not be read"})
        continue

    if _load_error is not None:
        _send({"err": "the candidate did not load: " + _load_error})
        continue

    try:
        _op = _message.get("op")
        if _op == "call":
            _name = _message.get("name")
            _target = _namespace.get(_name)
            if _target is None:
                raise NameError(str(_name))
            _value = _target(*(_message.get("args") or []), **(_message.get("kwargs") or {}))
        elif _op == "eval":
            _value = _evaluate(_message.get("src") or "")
        else:
            raise ValueError("unsupported op " + repr(_op))
        _send({"value": _value})
    except BaseException as error:  # noqa: BLE001 - the candidate's exception is the answer, whatever its base class
        # Reported BY NAME. The parent decides whether that name may become a live exception in the trusted process,
        # and it will not resolve anything that is not a builtins Exception subclass -- so naming SystemExit here is
        # an ordinary test failure over there, not an injected BaseException.
        _send({"exc": type(error).__name__, "msg": str(error)[:_MAX_MESSAGE_CHARS]})
